1	-- Calendar Demo Seed
2	-- Populates studio 6083ac92-6934-4170-943a-ec26e18c8943 with PDF-mockup data:
3	--   4 artists, 6 services (each with category), 1 demo client, 1 multi-session project,
4	--   10 bookings spread across today (LIVE / PAID / HOLD mix), 1 blocked time slot.
5	-- Idempotent via ON CONFLICT / NOT EXISTS guards. Safe to re-run.
6	
7	DO $$
8	DECLARE
9	  v_studio_id uuid := '6083ac92-6934-4170-943a-ec26e18c8943';
10	  v_artist_kaia uuid;
11	  v_artist_miles uuid;
12	  v_artist_sasha uuid;
13	  v_artist_guest uuid;
14	  v_service_neotrad uuid;
15	  v_service_fineline uuid;
16	  v_service_bg uuid;
17	  v_service_color uuid;
18	  v_service_script uuid;
19	  v_service_touchup uuid;
20	  v_client uuid;
21	  v_project uuid;
22	  v_today_8am timestamptz;
23	BEGIN
24	  v_today_8am := date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' + interval '8 hours';
25	
26	  -- ─── Artists (idempotent by display_name + studio_id) ────────────────────
27	  SELECT id INTO v_artist_kaia FROM artists WHERE studio_id=v_studio_id AND display_name='Kaia Okafor' LIMIT 1;
28	  IF v_artist_kaia IS NULL THEN
29	    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
30	    VALUES (v_studio_id, 'Kaia Okafor', ARRAY['Neo-traditional'], 1, 'active')
31	    RETURNING id INTO v_artist_kaia;
32	  END IF;
33	
34	  SELECT id INTO v_artist_miles FROM artists WHERE studio_id=v_studio_id AND display_name='Miles Vance' LIMIT 1;
35	  IF v_artist_miles IS NULL THEN
36	    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
37	    VALUES (v_studio_id, 'Miles Vance', ARRAY['Fine-line', 'Script'], 2, 'active')
38	    RETURNING id INTO v_artist_miles;
39	  END IF;
40	
41	  SELECT id INTO v_artist_sasha FROM artists WHERE studio_id=v_studio_id AND display_name='Sasha Reyes' LIMIT 1;
42	  IF v_artist_sasha IS NULL THEN
43	    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
44	    VALUES (v_studio_id, 'Sasha Reyes', ARRAY['Black & grey'], 3, 'active')
45	    RETURNING id INTO v_artist_sasha;
46	  END IF;
47	
48	  SELECT id INTO v_artist_guest FROM artists WHERE studio_id=v_studio_id AND display_name='Guest · Riley' LIMIT 1;
49	  IF v_artist_guest IS NULL THEN
50	    INSERT INTO artists (studio_id, display_name, specialties, sort_order, status)
51	    VALUES (v_studio_id, 'Guest · Riley', ARRAY['Color'], 4, 'active')
52	    RETURNING id INTO v_artist_guest;
53	  END IF;
54	
55	  -- ─── Services (idempotent by slug + studio_id) ──────────────────────────
56	  SELECT id INTO v_service_neotrad FROM services WHERE studio_id=v_studio_id AND slug='neo-traditional-sleeve' LIMIT 1;
57	  IF v_service_neotrad IS NULL THEN
58	    INSERT INTO services (studio_id, name, slug, duration_min, base_price_cents, deposit_cents, category, sort_order, is_public)
59	    VALUES (v_studio_id, 'Neo-traditional sleeve', 'neo-traditional-sleeve', 120, 34000, 10000, 'neo_traditional', 1, true)
60	    RETURNING id INTO v_service_neotrad;
61	  END IF;
62	
63	  SELECT id INTO v_service_fineline FROM services WHERE studio_id=v_studio_id AND slug='fine-line-tattoo' LIMIT 1;
64	  IF v_service_fineline IS NULL THEN
65	    INSERT INTO services (studio_id, name, slug, duration_min, base_price_cents, deposit_cents, category, sort_order, is_public)
66	    VALUES (v_studio_id, 'Fine-line tattoo', 'fine-line-tattoo', 60, 18000, 5000, 'fine_line', 2, true)
67	    RETURNING id INTO v_service_fineline;
68	  END IF;
69	
70	  SELECT id INTO v_service_bg FROM services WHERE studio_id=v_studio_id AND slug='black-grey' LIMIT 1;
71	  IF v_service_bg IS NULL THEN
72	    INSERT INTO services (studio_id, name, slug, duration_min, base_price_cents, deposit_cents, category, sort_order, is_public)
73	    VALUES (v_studio_id, 'Black & grey', 'black-grey', 90, 28000, 8000, 'black_grey', 3, true)
74	    RETURNING id INTO v_service_bg;
75	  END IF;
76	
77	  SELECT id INTO v_service_color FROM services WHERE studio_id=v_studio_id AND slug='color-piece' LIMIT 1;
78	  IF v_service_color IS NULL THEN
79	    INSERT INTO services (studio_id, name, slug, duration_min, base_price_cents, deposit_cents, category, sort_order, is_public)
80	    VALUES (v_studio_id, 'Color piece', 'color-piece', 180, 52000, 15000, 'color', 4, true)
81	    RETURNING id INTO v_service_color;
82	  END IF;
83	
84	  SELECT id INTO v_service_script FROM services WHERE studio_id=v_studio_id AND slug='script-tattoo' LIMIT 1;
85	  IF v_service_script IS NULL THEN
86	    INSERT INTO services (studio_id, name, slug, duration_min, base_price_cents, deposit_cents, category, sort_order, is_public)
87	    VALUES (v_studio_id, 'Script tattoo', 'script-tattoo', 120, 34000, 10000, 'fine_line', 5, true)
88	    RETURNING id INTO v_service_script;
89	  END IF;
90	
91	  SELECT id INTO v_service_touchup FROM services WHERE studio_id=v_studio_id AND slug='touch-up' LIMIT 1;
92	  IF v_service_touchup IS NULL THEN
93	    INSERT INTO services (studio_id, name, slug, duration_min, base_price_cents, deposit_cents, category, sort_order, is_public)
94	    VALUES (v_studio_id, 'Touch-up', 'touch-up', 60, 15000, 0, 'other', 6, true)
95	    RETURNING id INTO v_service_touchup;
96	  END IF;
97	
98	  -- ─── Demo clients (idempotent by email) ─────────────────────────────────
99	  SELECT id INTO v_client FROM clients WHERE studio_id=v_studio_id AND email='demo.client@inkos.test' LIMIT 1;
100	  IF v_client IS NULL THEN
101	    INSERT INTO clients (studio_id, first_name, last_name, email, phone)
102	    VALUES (v_studio_id, 'Asha', 'Mehra', 'demo.client@inkos.test', '+15551234567')
103	    RETURNING id INTO v_client;
104	  END IF;
105	
106	  -- ─── Multi-session project ──────────────────────────────────────────────
107	  SELECT id INTO v_project FROM projects WHERE studio_id=v_studio_id AND name='M. Vance sleeve · 3 sessions' LIMIT 1;
108	  IF v_project IS NULL THEN
109	    INSERT INTO projects (studio_id, client_id, primary_artist_id, name, total_sessions_planned, sessions_completed, total_price_cents, status)
110	    VALUES (v_studio_id, v_client, v_artist_miles, 'M. Vance sleeve · 3 sessions', 3, 1, 102000, 'active')
111	    RETURNING id INTO v_project;
112	  END IF;
113	
114	  -- ─── Today's bookings — wipe prior demo ones + re-insert ────────────────
115	  -- Demo bookings tagged in metadata so we don't nuke real user bookings
116	  DELETE FROM bookings
117	    WHERE studio_id=v_studio_id
118	      AND (metadata->>'demo_seed')::boolean = true
119	      AND scheduled_at::date = CURRENT_DATE;
120	
121	  -- 11 AM — P. Lin · B&G · PAID (completed + deposit_paid)
122	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, metadata)
123	  VALUES (v_studio_id, v_client, v_artist_sasha, v_service_bg,
124	    v_today_8am + interval '3 hours', v_today_8am + interval '4 hours 30 minutes', 90,
125	    'completed', 28000, 8000, true, '{"demo_seed": true, "client_label": "P. Lin"}'::jsonb);
126	
127	  -- 12 PM — Devon Whitaker · Neo-trad · PAID
128	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, metadata)
129	  VALUES (v_studio_id, v_client, v_artist_kaia, v_service_neotrad,
130	    v_today_8am + interval '4 hours', v_today_8am + interval '6 hours', 120,
131	    'completed', 34000, 10000, true, '{"demo_seed": true, "client_label": "Devon Whitaker"}'::jsonb);
132	
133	  -- 12 PM — T. Nguyen · Color · HOLD (pending + unpaid + deposit required)
134	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, deposit_deadline_override, metadata)
135	  VALUES (v_studio_id, v_client, v_artist_guest, v_service_color,
136	    v_today_8am + interval '4 hours', v_today_8am + interval '7 hours', 180,
137	    'pending', 52000, 15000, false, now() + interval '18 hours', '{"demo_seed": true, "client_label": "T. Nguyen"}'::jsonb);
138	
139	  -- 1 PM — J. Cho · Fine-line · PAID
140	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, metadata)
141	  VALUES (v_studio_id, v_client, v_artist_miles, v_service_fineline,
142	    v_today_8am + interval '5 hours', v_today_8am + interval '6 hours', 60,
143	    'completed', 18000, 5000, true, '{"demo_seed": true, "client_label": "J. Cho"}'::jsonb);
144	
145	  -- 2 PM — R. Patel · Neo-trad · LIVE (in_progress)
146	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, metadata)
147	  VALUES (v_studio_id, v_client, v_artist_kaia, v_service_neotrad,
148	    v_today_8am + interval '6 hours', v_today_8am + interval '9 hours', 180,
149	    'in_progress', 52000, 15000, true, '{"demo_seed": true, "client_label": "R. Patel"}'::jsonb);
150	
151	  -- 2 PM — M. Vance project · Script · LIVE · S2/3
152	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, project_id, session_number, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, metadata)
153	  VALUES (v_studio_id, v_client, v_artist_miles, v_service_script, v_project, 2,
154	    v_today_8am + interval '6 hours', v_today_8am + interval '8 hours', 120,
155	    'in_progress', 34000, 10000, true, '{"demo_seed": true, "client_label": "Asha M. (S2/3)"}'::jsonb);
156	
157	  -- 3 PM — Asha Mehra · Guest · Touch-up · PAID (slot after Guest's 12-3pm HOLD booking)
158	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, metadata)
159	  VALUES (v_studio_id, v_client, v_artist_guest, v_service_touchup,
160	    v_today_8am + interval '7 hours', v_today_8am + interval '8 hours', 60,
161	    'confirmed', 15000, 0, false, '{"demo_seed": true, "client_label": "Asha Mehra"}'::jsonb);
162	
163	  -- 4 PM — Cleo Benítez · Color · confirmed (S1/4)
164	  INSERT INTO bookings (studio_id, client_id, artist_id, service_id, scheduled_at, end_at, duration_min, status, price_cents, deposit_cents, deposit_paid, metadata)
165	  VALUES (v_studio_id, v_client, v_artist_sasha, v_service_color,
166	    v_today_8am + interval '8 hours', v_today_8am + interval '10 hours', 120,
167	    'confirmed', 52000, 15000, true, '{"demo_seed": true, "client_label": "Cleo Benítez"}'::jsonb);
168	
169	  RAISE NOTICE 'Demo seed complete for studio %', v_studio_id;
170	END $$;
171	
172	-- Blocked time — Sasha at lunch (12-1 PM)
173	INSERT INTO artist_blocked_dates (studio_id, artist_id, blocked_date, reason)
174	SELECT
175	  '6083ac92-6934-4170-943a-ec26e18c8943',
176	  id,
177	  CURRENT_DATE,
178	  'Lunch'
179	FROM artists
180	WHERE studio_id='6083ac92-6934-4170-943a-ec26e18c8943' AND display_name='Sasha Reyes'
181	ON CONFLICT DO NOTHING;
182	

